new_semver = r'''"""
Python helper for Semantic Versioning (http://semver.org/)
"""

import argparse
import collections
import re
import sys


__version__ = '2.8.1'
__author__ = 'Kostiantyn Rybnikov'
__author_email__ = 'k-bx@k-bx.com'
__maintainer__ = 'Sebastien Celles'
__maintainer_email__ = "s.celles@gmail.com"

_REGEX = re.compile(
        r"""
        ^
        (?P<major>(?:0|[1-9][0-9]*))
        \.
        (?P<minor>(?:0|[1-9][0-9]*))
        \.
        (?P<patch>(?:0|[1-9][0-9]*))
        (\-(?P<prerelease>
            (?:0|[1-9A-Za-z-][0-9A-Za-z-]*)
            (\.(?:0|[1-9A-Za-z-][0-9A-Za-z-]*))*
        ))?
        (\+(?P<build>
            [0-9A-Za-z-]+
            (\.[0-9A-Za-z-]+)*
        ))?
        $
        """, re.VERBOSE)

_LAST_NUMBER = re.compile(r'(?:[^\d]*(\d+)[^\d]*)+')


def cmp(a, b):
    """Compare two version info objects."""
    return (a > b) - (a < b)


def parse(version):
    """
    Parses a raw string and returns a dictionary with five keys:
    major, minor, patch, prerelease and build.

    :param version: the raw version string.
    :returns: dict, with 5 keys.  Each key is string or integer value.
    :raises ValueError: if version is not valid.
    """
    m = _REGEX.match(version)
    if not m:
        raise ValueError("Invalid version string '{}'".format(version))
    d = m.groupdict()
    major = int(d['major'])
    minor = int(d['minor'])
    patch = int(d['patch'])
    prerelease = (
        '.'.join([str(s) for s in d['prerelease'].split('.')])
        if d.get('prerelease') is not None else None
    )
    build = '.'.join([str(s) for s in d['build'].split('.')]) if d.get('build') is not None else None
    return {'major': major, 'minor': minor, 'patch': patch,
            'prerelease': prerelease, 'build': build}


class VersionInfo(object):
    """Helper class which helps to manipulate versions."""

    __slots__ = ('_major', '_minor', '_patch', '_prerelease', '_build')

    def __init__(self, major, minor, patch, prerelease=None, build=None):
        # R5: Type coercion
        self._major = int(major)
        self._minor = int(minor)
        self._patch = int(patch)
        self._prerelease = str(prerelease) if prerelease is not None else None
        self._build = str(build) if build is not None else None

    def __setattr__(self, name, value):
        # R1: Block all attribute assignments (including new ones)
        if name in self.__slots__:
            raise AttributeError("'{}' attribute of '{}' must be readonly".format(
                name, type(self).__name__))
        raise AttributeError("'{}' object has no attribute '{}'".format(
            type(self).__name__, name))

    @property
    def major(self):
        return self._major

    @property
    def minor(self):
        return self._minor

    @property
    def patch(self):
        return self._patch

    @property
    def prerelease(self):
        return self._prerelease

    @property
    def build(self):
        return self._build

    def _astuple(self):
        return (self.major, self.minor, self.patch,
                self.prerelease, self.build)

    def _asdict(self):
        return {'major': self.major, 'minor': self.minor, 'patch': self.patch,
                'prerelease': self.prerelease, 'build': self.build}

    def __eq__(self, other):
        return self._compare(other) == 0

    def __ne__(self, other):
        return self._compare(other) != 0

    def __lt__(self, other):
        return self._compare(other) < 0

    def __le__(self, other):
        return self._compare(other) <= 0

    def __gt__(self, other):
        return self._compare(other) > 0

    def __ge__(self, other):
        return self._compare(other) >= 0

    def _compare(self, other):
        """Compare self with other. Returns -1, 0, or 1."""
        if isinstance(other, VersionInfo):
            return _compare_by_keys(self, other,
                                    lambda x, y: x is None if y is None else (x < y) - (x > y),
                                    ['prerelease'])
        elif isinstance(other, tuple):
            # R3: Support tuple comparison
            if len(other) < 3 or len(other) > 5:
                return NotImplemented
            o_dict = {
                'major': other[0],
                'minor': other[1],
                'patch': other[2],
                'prerelease': other[3] if len(other) > 3 else None,
                'build': other[4] if len(other) > 4 else None,
            }
            return _compare_by_keys(self, o_dict,
                                    lambda x, y: x is None if y is None else (x < y) - (x > y),
                                    ['prerelease'])
        elif isinstance(other, dict):
            return _compare_by_keys(self, other,
                                    lambda x, y: x is None if y is None else (x < y) - (x > y),
                                    ['prerelease'])
        else:
            # R3: Disallow comparison with str, int, etc.
            return NotImplemented

    def __repr__(self):
        s = "{}(major={}, minor={}, patch={}".format(
            type(self).__name__, self.major, self.minor, self.patch)
        if self.prerelease is not None:
            s += ", prerelease={!r}".format(self.prerelease)
        if self.build is not None:
            s += ", build={!r}".format(self.build)
        s += ')'
        return s

    def __str__(self):
        return format_version(self)

    def __hash__(self):
        return hash((self.major, self.minor, self.patch,
                     self.prerelease, self.build))

    def __iter__(self):
        # R2: Make iterable
        yield self.major
        yield self.minor
        yield self.patch
        yield self.prerelease
        yield self.build

    @staticmethod
    def parse(version):
        """
        Converts a string to a VersionInfo object.

        :param version: a version string
        :returns: VersionInfo instance
        """
        d = parse(version)
        return VersionInfo(d['major'], d['minor'], d['patch'],
                           d['prerelease'], d['build'])

    # R4: Instance bump methods
    def bump_major(self):
        """Return a new VersionInfo with major incremented."""
        return VersionInfo(self.major + 1, 0, 0)

    def bump_minor(self):
        """Return a new VersionInfo with minor incremented."""
        return VersionInfo(self.major, self.minor + 1, 0)

    def bump_patch(self):
        """Return a new VersionInfo with patch incremented."""
        return VersionInfo(self.major, self.minor, self.patch + 1)

    def bump_prerelease(self, token='rc'):
        """Return a new VersionInfo with prerelease incremented."""
        if self.prerelease is None:
            return VersionInfo(self.major, self.minor, self.patch,
                               '{}.1'.format(token))
        parts = self.prerelease.split('.')
        try:
            i = len(parts) - 1
            parts[i] = _increment_string(parts[i])
        except ValueError:
            raise ValueError("Cannot bump prerelease '{}'".format(self.prerelease))
        return VersionInfo(self.major, self.minor, self.patch,
                           '.'.join(parts))

    def bump_build(self):
        """Return a new VersionInfo with build incremented."""
        if self.build is None:
            return VersionInfo(self.major, self.minor, self.patch,
                               build='1')
        parts = self.build.split('.')
        try:
            i = len(parts) - 1
            parts[i] = _increment_string(parts[i])
        except ValueError:
            raise ValueError("Cannot bump build '{}'".format(self.build))
        return VersionInfo(self.major, self.minor, self.patch,
                           prerelease=self.prerelease,
                           build='.'.join(parts))

    # R7: replace method
    def replace(self, **kwargs):
        """Return a new VersionInfo with specified components replaced."""
        major = kwargs.get('major', self.major)
        minor = kwargs.get('minor', self.minor)
        patch = kwargs.get('patch', self.patch)
        prerelease = kwargs.get('prerelease', self.prerelease)
        build = kwargs.get('build', self.build)
        return VersionInfo(major, minor, patch, prerelease, build)


def _to_dict(version_info):
    """Convert a VersionInfo object to a dictionary."""
    return {'major': version_info.major,
            'minor': version_info.minor,
            'patch': version_info.patch,
            'prerelease': version_info.prerelease,
            'build': version_info.build}


def parse_version_info(version):
    """
    Parse a version string and return a VersionInfo object.

    :param version: the version string to parse.
    :returns: an instance of VersionInfo
    :raises: ValueError on invalid input.
    """
    return VersionInfo.parse(version)


def _nat_cmp(a, b):
    def cmp_nat(a, b):
        a, b = a.lower(), b.lower()
        comp = 0
        find = re.compile(r'([A-Za-z][0-9]|[1-9][0-9]*|[^A-Za-z\d])')
        a_list = find.findall(a)
        b_list = find.findall(b)
        while comp == 0 and len(a_list) and len(b_list):
            a_str = a_list[0]
            b_str = b_list[0]
            if a_str.isdigit() and b_str.isdigit():
                comp = int(a_str) - int(b_str)
            elif a_str.isdigit():
                comp = 1
            elif b_str.isdigit():
                comp = -1
            else:
                comp = cmp(a_str, b_str)
            a_list.pop(0)
            b_list.pop(0)
        if not len(a_list) and not len(b_list) and comp == 0:
            return 0
        elif not len(a_list):
            return -1
        elif not len(b_list):
            return 1
        else:
            return comp

    res = cmp_nat(a, b)
    if res < 0:
        return -1
    elif res > 0:
        return 1
    else:
        return 0


def _compare_by_keys(left, right, keycmp, keys):
    """Compare two version like structures by a list of keys.

    left, right: dictionaries or VersionInfo objects
    keycmp: function used to compare values for a given key
    keys: ordered list of keys to use for comparing
    """
    if not isinstance(left, dict):
        left = _to_dict(left)
    if not isinstance(right, dict):
        right = _to_dict(right)
    for key in keys:
        res = keycmp(left.get(key), right.get(key))
        if res != 0:
            return res
    return 0


def compare(left, right):
    """
    Compare two version strings/objects.

    A special order is applied on version strings containing release
    candidate and alpha/beta tags.

    For example: 1.0.0-alpha < 1.0.0-rc1 < 1.0.0.

    :param left: version string, VersionInfo, or dictionary
    :param right: version string, VersionInfo, or dictionary
    :return: -1 if left < right, 0 if left == right, 1 if left > right
    """
    if isinstance(left, str):
        left = VersionInfo.parse(left)
    if isinstance(right, str):
        right = VersionInfo.parse(right)
    if isinstance(left, tuple):
        left = VersionInfo(*left)
    if isinstance(right, tuple):
        right = VersionInfo(*right)
    if not isinstance(left, VersionInfo):
        left = VersionInfo(**left)
    if not isinstance(right, VersionInfo):
        right = VersionInfo(**right)
    return _compare_by_keys(left, right,
                            lambda x, y: x is None if y is None else (x < y) - (x > y),
                            ['major', 'minor', 'patch', 'prerelease'])


def match(version, expression):
    """
    Checks whether the version matches the given expression.

    For example 2.0.1-alpha.1 will match 2.0.1-rc.* but not 2.0.0-rc.*

    :param version: a version string
    :param expression: the expression to check against
    :return: True if version matches expression, False otherwise
    """
    if not expression:
        return False
    if not version:
        return False
    try:
        ver_info = VersionInfo.parse(version)
    except ValueError:
        return False
    # Convert the expression to regex
    escaped = re.escape(expression)
    pattern = escaped.replace(r'\*', '.*').replace(r'\?', '.')
    regex = '^' + pattern + '$'
    return bool(re.match(regex, str(ver_info)))


def max_ver(*versions):
    """
    Given a list of versions, returns the maximal one.

    :param versions: list of version strings or VersionInfo objects
    :returns: the maximal version
    """
    return max(versions, key=lambda v: VersionInfo.parse(v) if isinstance(v, str) else v)


def min_ver(*versions):
    """
    Given a list of versions, returns the minimal one.

    :param versions: list of version strings or VersionInfo objects
    :returns: the minimal version
    """
    return min(versions, key=lambda v: VersionInfo.parse(v) if isinstance(v, str) else v)


def format_version(version_info):
    """
    Formats a VersionInfo object to a version string.

    :param version_info: a VersionInfo object
    :returns: a version string in the format ``major.minor.patch(-prerelease)(+build)``
    """
    if not isinstance(version_info, VersionInfo):
        version_info = VersionInfo(**version_info)
    result = "{0}.{1}.{2}".format(version_info.major,
                                  version_info.minor,
                                  version_info.patch)
    if version_info.prerelease is not None:
        result += "-{0}".format(version_info.prerelease)
    if version_info.build is not None:
        result += "+{0}".format(version_info.build)
    return result


def _increment_string(string):
    """
    Look for the numeric section of the given string. Return a new string
    with that number incremented by 1, and the suffix changed.

    If there's no suffix, add '1'.

    :param string: the string to increment
    :returns: new string with incremented number
    :raises ValueError: if the string doesn't end with a number
    """
    match = _LAST_NUMBER.search(string)
    if not match:
        raise ValueError("Could not increment string '{}'".format(string))
    prefix = string[:match.start()]
    num = match.group(1)
    if len(num) > 1 and num.startswith('0'):
        raise ValueError("Zero-padded numbers are not supported")
    return "{}{}".format(prefix, int(num) + 1)


def bump_major(version):
    """
    Bump the major version number.

    :param version: a version string, VersionInfo, or dictionary
    :returns: a new version string with major bumped
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return VersionInfo(version.major + 1, 0, 0)


def bump_minor(version):
    """
    Bump the minor version number.

    :param version: a version string, VersionInfo, or dictionary
    :returns: a new version string with minor bumped
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return VersionInfo(version.major, version.minor + 1, 0)


def bump_patch(version):
    """
    Bump the patch version number.

    :param version: a version string, VersionInfo, or dictionary
    :returns: a new version string with patch bumped
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return VersionInfo(version.major, version.minor, version.patch + 1)


def bump_prerelease(version, token='rc'):
    """
    Bump the prerelease version number.

    :param version: a version string, VersionInfo, or dictionary
    :param token: the prerelease token (default 'rc')
    :returns: a new version string with prerelease bumped
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return version.bump_prerelease(token)


def bump_build(version):
    """
    Bump the build metadata version number.

    :param version: a version string, VersionInfo, or dictionary
    :returns: a new version string with build bumped
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return version.bump_build()


def finalize_version(version):
    """
    Finalize a version by removing prerelease/build metadata.

    :param version: a version string, VersionInfo, or dictionary
    :returns: a new version string without prerelease/build
    """
    if isinstance(version, str):
        version = VersionInfo.parse(version)
    return VersionInfo(version.major, version.minor, version.patch)


# R6: CLI functions
def createparser():
    """Create and return the argument parser for pysemver CLI."""
    parser = argparse.ArgumentParser(
        prog='pysemver',
        description='Command-line interface for semantic versioning operations.'
    )
    subparsers = parser.add_subparsers(dest='command')

    # bump command
    bump_parser = subparsers.add_parser('bump', help='Bump a version component')
    bump_parser.add_argument('version', help='Version string')
    bump_group = bump_parser.add_mutually_exclusive_group(required=True)
    bump_group.add_argument('--major', action='store_true', help='Bump major')
    bump_group.add_argument('--minor', action='store_true', help='Bump minor')
    bump_group.add_argument('--patch', action='store_true', help='Bump patch')
    bump_group.add_argument('--prerelease', nargs='?', const='rc', default=None,
                            help='Bump prerelease (with optional token)')
    bump_group.add_argument('--build', action='store_true', help='Bump build')

    # compare command
    compare_parser = subparsers.add_parser('compare', help='Compare two versions')
    compare_parser.add_argument('left', help='Left version')
    compare_parser.add_argument('right', help='Right version')

    # match command
    match_parser = subparsers.add_parser('match', help='Check if version matches pattern')
    match_parser.add_argument('version', help='Version string')
    match_parser.add_argument('pattern', help='Pattern to match')

    # replace command
    replace_parser = subparsers.add_parser('replace', help='Replace version components')
    replace_parser.add_argument('version', help='Version string')
    replace_parser.add_argument('--major', type=int, help='Replace major')
    replace_parser.add_argument('--minor', type=int, help='Replace minor')
    replace_parser.add_argument('--patch', type=int, help='Replace patch')
    replace_parser.add_argument('--prerelease', help='Replace prerelease')
    replace_parser.add_argument('--build', help='Replace build')

    return parser


def process(args):
    """Process command-line arguments and produce output."""
    command = args.command

    if command == 'bump':
        vi = VersionInfo.parse(args.version)
        if args.major:
            result = vi.bump_major()
        elif args.minor:
            result = vi.bump_minor()
        elif args.patch:
            result = vi.bump_patch()
        elif args.prerelease is not None:
            result = vi.bump_prerelease(args.prerelease)
        elif args.build:
            result = vi.bump_build()
        print(result)

    elif command == 'compare':
        left = args.left
        right = args.right
        result = compare(left, right)
        if result < 0:
            print("{} < {}".format(left, right))
        elif result > 0:
            print("{} > {}".format(left, right))
        else:
            print("{} == {}".format(left, right))

    elif command == 'match':
        result = match(args.version, args.pattern)
        print(result)

    elif command == 'replace':
        vi = VersionInfo.parse(args.version)
        kwargs = {}
        if args.major is not None:
            kwargs['major'] = args.major
        if args.minor is not None:
            kwargs['minor'] = args.minor
        if args.patch is not None:
            kwargs['patch'] = args.patch
        if args.prerelease is not None:
            kwargs['prerelease'] = args.prerelease
        if args.build is not None:
            kwargs['build'] = args.build
        result = vi.replace(**kwargs)
        print(result)

    else:
        print("Unknown command: {}".format(command), file=sys.stderr)
        sys.exit(1)


def main():
    """Main entry point for pysemver CLI."""
    parser = createparser()
    args = parser.parse_args()
    if args.command is None:
        parser.print_help()
        sys.exit(1)
    process(args)


# R7: Module-level replace function
def replace(version, **kwargs):
    """
    Replace version components and return a new version string.

    :param version: a version string
    :param kwargs: components to replace (major, minor, patch, prerelease, build)
    :returns: a new version string with replaced components
    """
    vi = VersionInfo.parse(version)
    result = vi.replace(**kwargs)
    return format_version(result)


